using Microsoft.AspNetCore.Builder;using Microsoft.AspNetCore.Http;using Microsoft.AspNetCore.Routing;using Mbb.Archive.BuildingBlocks.Presentation;using Mbb.Archive.Modules.AccessControl.Application.Roles;namespace Mbb.Archive.Modules.AccessControl.Presentation;public static class AccessEndpoints{public static IEndpointRouteBuilder MapAccessEndpoints(this IEndpointRouteBuilder e){var g=e.MapGroup("/api/v1/access").WithTags("Access Control").RequireAuthorization("permission:access.admin");g.MapPost("/roles",async(CreateRoleCommand c,CreateRoleCommandHandler h,CancellationToken ct)=>{var r=await h.Handle(c,ct);return r.IsFailure?ApiResults.Problem(r.Error):Results.Created($"/api/v1/access/roles/{r.Value}",new{id=r.Value});});g.MapPost("/roles/{id:guid}/permissions",async(Guid id,PermissionRequest req,GrantPermissionCommandHandler h,CancellationToken ct)=>{var r=await h.Handle(new GrantPermissionCommand(id,req.Permission),ct);return r.IsFailure?ApiResults.Problem(r.Error):Results.NoContent();});g.MapPost("/subjects/{subjectId}/roles/{roleId:guid}",async(string subjectId,Guid roleId,AssignRoleCommandHandler h,CancellationToken ct)=>{var r=await h.Handle(new AssignRoleCommand(subjectId,roleId),ct);return r.IsFailure?ApiResults.Problem(r.Error):Results.NoContent();});return e;}private sealed record PermissionRequest(string Permission);}
